INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter23-telangana-adi-hindu-movement', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter23-telangana-adi-hindu-movement-p1", "partName": "Madari Bhagya Reddy Varma", "bodyMd": "The Adi-Hindu movement emerged in Hyderabad state to fight discrimination against Dalits, untouchability, and caste differences. **Madari Bhagya Reddy Varma** was the central figure behind this movement.\n\nBhagya Reddy Varma is regarded as the **Father of the Telangana Dalit Movement** and was named the **\"Dalit Vaithalika.\"**\n\n### Early Life\n\n*   Born on **22nd May, 1888** into a \"Mala\" family in Hyderabad, to Madari Venkaiah and Rangamamba.\n*   His original name was **Madari Bhagaiah**; his family guru renamed him Bhagya Reddy.\n*   **Raavichettu Ranga Rao** financially supported his education.\n*   He left home during childhood due to a family issue and joined a Roman Catholic Brothers'' Tennis Court as a tennis ball boy, growing close to the Catholic Church family.\n*   He later worked as an electrician in the electricity department, and subsequently joined the **Brahma Samaj** and **Arya Samaj**.\n\n### Titles\n\n| Title | Given By |\n|---|---|\n| Varma | Balaji Krishna Rao (Arya Samaj member, recognizing his services to Arya Samaj) |\n| Shiva Shresta | Vaman Nayak |\n| Sangamanya | Given at the Adi Andhra Mahasabha held in Elluru |\n\n### Religious and Literary Contributions\n\n*   He was drawn to Buddhism and celebrated **Buddha Jayanthi** every year from **1913 to 1937** (first celebrated in 1913 on Vaishaka Shudda Purnima; last celebrated under his leadership on **25th May, 1937**).\n*   He wrote **\"Vetti Madiga,\"** the first Dalit story in Telugu literature.\n\n### Organizations Established\n\nBhagya Reddy Varma founded a series of organizations as part of the Adi Hindu movement:\n\n| Organization | Year |\n|---|---|\n| Jagan Mitra Mandali | 1906 |\n| Adi Hindu Karyakartala Dalam | 1906 |\n| Vaidika Dharma Prachaini Sabha | 1910 |\n| Manya Sangam | 1911 |\n| Ahimsa Samajam | 1912 |\n| Swastik Volunteers Sangam | 1912 |\n| Jeeva Raksha Gnana Pracharak Mandali | 1915 |\n| Vishwa Gruha Paricharak Sammelanam | 1916 |\n| Adi Hindu Social Service League | 1922 |\n\n**Jagan Mitra Mandali (1906):** Established with the aim of spreading awareness among Dalits, promoting educational development, and uniting them.\n\n*   In 1910, a primary school was established at Islamia Bazar under this initiative; many more Adi Hindu Schools followed.\n*   In 1929, **Gandhiji visited** the Adi Hindu School established by Bhagya Reddy Varma.\n*   At a meeting organized by Bhagya Reddy Varma at **Victory Play Ground, Chaderghat**, Gandhiji warned Hindus that practicing untouchability is a sin and a bad mark for Hinduism.\n*   From 1934, the **Nizam government** took over responsibility for **26 Adi Hindu Schools** founded by Bhagya Reddy Varma.\n*   Separately, schools for Dalit girls in Hyderabad were first established by **Katta Ramakka** and **Jangam Sarvaiah**; Katta Ramakka started a school in front of her house at Secunderabad Kalva Basthi for Dalit girls.\n\n**Manya Sangam:** Jagan Mitra Mandali (1906) was renamed Manya Sangam in 1911, and later renamed **Adi Hindu Social Service League** in 1922. Valthati Sheshaiah was the president of the Manya Sangam working committee.\n\nImportant programs of Manya Sangam:\n\n*   Spreading awareness regarding education.\n*   Abolition of the Devadasi and Jogini systems.\n*   Abolition of child marriages.\n*   Ban of alcohol.\n*   Prohibiting meat on special occasions.\n\nRelated initiatives:\n\n*   Bhagya Reddy Varma established a **Devadasi eradication organization** to abolish the Devadasi system.\n*   In 1915, he established the **Sanga Samskara Nataka Mandali**, having Harijans perform dramas.\n*   In 1916, he established the **Vishwa Gruha Paricharika Sammelanam**, which worked for the welfare of maid servants.\n\n### Self-Respect Movement and Adi Andhra Conferences\n\nBhagya Reddy Varma led self-respect movements for Dalits in both Hyderabad and the Andhra region.\n\n*   In 1917, the **1st Adi Andhra Conference** (also called the 1st Pradeshika Panchama Mahajana Sabha) was held in Vijayawada by **Guduru Ramachandra Rao**, with **Bhagya Reddy Varma as president**.\n*   At this meeting, he named Dalits as **\"Adi Hindus\"** and urged them to identify by that name.\n\n### Adi Hindu League Conferences (1921–24)\n\nFour Adi Hindu League Conferences were held in Hyderabad under Bhagya Reddy Varma''s leadership between 1921 and 1924.\n\n*   **1st Conference (1921):** Presided over by **Papanna**. **Kusuma Dharmanna**, an attendee, sang the song **\"Maa Koddhu Nalla Dorathanam.\"**\n*   **2nd Conference (1922):** Presided over by **Keshav Rao Koratkar**.\n\n### All India Adi Hindu Social Conference (1922)\n\n*   In March 1922, Bhagya Reddy Varma organized the **1st All India Adi Hindu Social Conference** at Residency Bazar, Hyderabad. **M.L. Adaiah** presided over this conference.\n*   Due to his sustained efforts, the terms \"Panchama\" and \"Parayalu\" were removed from government records — communities began to be officially called **Adi Dravida** (in Tamil regions) and **Adi Andhra** (in Andhra regions), as per a **G.O. issued by the Madras Government on 25th March, 1922**.\n\n### Adi Hindu Sabha and Related Activities (1925)\n\n*   In 1925, Bhagya Reddy Varma organized the **Adi Hindu Sabha**, with **Subedar Sayanna** (prominently known as a leader of the Arundhatis) as president.\n*   In 1925, he organized an exhibition of portraits and sculptures created by Adi-Hindus at Residency Bazar, Hyderabad.\n*   In 1925, he conducted **Adi Hindu Youth Gymnastic competitions** at Prem Theater Ground, Hyderabad, under the leadership of **Kodi Rammoorthy Nayudu**, to encourage Adi-Hindu youth.\n*   When **Plague and Cholera** spread in Hyderabad in 1925, he established **Volunteer Medical Camps** for prevention and treatment.\n\n### National-Level Activities (1927–1931)\n\n*   **1927:** Represented South India at the **All India Downtrodden Castes Conference** held at Allahabad.\n*   **March 1927:** Presided over the **Mathangi Sabha** held at Mallepalli, where a resolution was passed banning alcohol.\n*   **November 1930:** Attended the **All India Adi Hindu Conference** held at Allahabad.\n*   **27–28 September 1931:** Elected president of the **All India Adi Hindu Special Conference** held at Lucknow, attended by representatives from across the country, who demanded **separate constituencies for Dalits**.\n    *   At this conference, a unanimous resolution was passed electing **Dr. B.R. Ambedkar** as the sole representative of the 9 crore Adi Hindu Samaj of India.\n    *   Bhagya Reddy Varma **renounced the title \"Varma\"** from his name at this conference, after a participant pointed out that the term denoted upper caste.\n*   **November 1931:** The **Adi Hindu Political Conference** was held at Bollarum, Secunderabad, presided over by Bhagya Reddy Varma.\n    *   **Bandhela Chittaraiah** chaired the Invitation Committee.\n    *   **Vemula Kurmaiah**, president of the Andhra State Independent Adijana Conference, inaugurated the conference.\n    *   With Ambedkar as leader, resolutions were passed for the **abolition of Vetti** and for the **appointment of Adi Hindus in military and police jobs**.\n*   Bhagya Reddy Varma also participated in the **Andhra Mahasabha**, passing several resolutions related to Dalits.\n*   Due to his efforts, the **Nizam government officially recorded untouchables as \"Adi-Hindus\" in the 1931 census**.\n\n### Later Life and Legacy\n\n*   In 1937, he founded the **Jambavarna Seva Samithi**, which worked for the upliftment of Dalits.\n*   Bhagya Reddy Varma also ran a **parallel judicial system** in Telangana, conducting **Nyaya Panchayats** at the village level with the help of his disciples.\n*   He died in **February 1939**.\n*   After his death, his son **M.B. Goutham** established the Adi Hindu Social Service organization.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter23-telangana-adi-hindu-movement-p2", "partName": "Arige Ramaswamy", "bodyMd": "*   Born in **Ramankola, Ranga Reddy district, in 1875**; completed his studies at Secunderabad.\n*   Worked as an office boy, a carpenter, and later as a **Ticket Collector for Nizam Railways**.\n*   Spread the principles of **Vaishnavism, Brahma Samaj, and the doctrine of Achala**.\n*   Established the **Sunitha Bala Samajam in 1912** at Secunderabad, working for Dalit education, abolition of the Devadasi system, and prohibition of alcohol.\n\n**Adi Hindu Jathiyonnathi Sabha:**\n\n*   Established by Arige Ramaswamy in **1922** to work for the upliftment of Hindu society and the eradication of the Devadasi system.\n*   President: **Konda Venkat Swamy**; Secretaries: **Papayya** and **Arige Ramaswamy**.\n*   Main aims: opposing the concept of Shudras/Neecha Janma theory, and establishing equality among people.\n*   In **1927**, it was renamed the **Adi Hindu Mahasabha**.\n\nLater activities:\n\n*   In 1931, he established the **Arundhatiya Mahasabha**, and on **1st June 1931** conducted the Arundatiya conference at the Reddy hostel of Nizam State.\n*   In 1934, contesting on behalf of the Adi Hindu Social Service League, he was elected the **1st Dalit Councillor in the Hyderabad Municipal Corporation**.\n*   He was the only Dalit poet to take part in the **Golconda Kavula Sanchika**, published by **Suravaram Pratap Reddy**.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter23-telangana-adi-hindu-movement-p3", "partName": "B.S. Venkat Rao", "bodyMd": "Known as **\"Hyderabad Ambedkar,\"** B.S. Venkat Rao was born on **11th December, 1898** at Hyderabad. His original name was **Bathula Ashaiah**, and he was popularly known as **\"Rao Saheb\"** among his followers.\n\n*   Worked at the Nizam government engineering college, and later in the Nizamsagar project department of the Nizam''s government.\n*   In **1922**, established the **Adi Dravida Sangam**, aimed at eradicating the Devadasi system and bringing awareness and unity among Dalits.\n*   In **1927**, founded the **Adi Hindu Mahasabha**, under which he built libraries and temples for Dalits at Ghasmandi, Secunderabad (later renamed **Adeyya Nagar**).\n*   Presided over the **Mahar Mahasabha** held at Pune in **May 1936**.\n*   In **1936**, established the **Ambedkar Youth League** for the upliftment of Dalit youth.\n*   In **1938**, established the **Hyderabad State Depressed Classes Association**.\n*   Convinced the Nizam to create the **Scheduled Castes Trust Fund**, with **1 crore rupees** for Dalit development — the first welfare fund of its kind in the country.\n*   Established the **Adi Hindu Library**.\n\n### Political Career\n\n| Year | Position |\n|---|---|\n| 1938 | Secunderabad Cantonment Board member |\n| 1939 | Hyderabad Municipal Councillor |\n| 1946 | Member of Legislative Assembly (MLA) from local bodies |\n| 1947 | Education Minister, Mir Layak Ali cabinet |\n| 1952 | Rajya Sabha member from Hyderabad Legislative Assembly |\n\nAs recognition for his services, the Nizam awarded him the title **\"Khusro-e-Alim.\"**", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter23-telangana-adi-hindu-movement-p4", "partName": "Other Leaders of the Adi-Hindu Movement", "bodyMd": "### M.L. Adeyya\n\n*   Called the **\"Bhishma of Dalit Communities.\"**\n*   In **1906**, established a school for Adi Hindus named **\"Sir William Barter\"** at Secunderabad, on land donated by William Barter.\n*   The school was later renamed the **M.L. Adeyya Memorial High School**.\n\n### Peesari Veeranna\n\n*   In 1937, when Gandhiji visited Hyderabad, Peesari Veeranna **opposed the word \"Harijan\"** used by Gandhiji, arguing that the community should be called Adi-Hindus instead.\n*   He fought against **Vetti**, urging villagers not to perform it.\n\n### B. Shyam Sunder\n\n*   Authored the book **\"They Burn,\"** describing the conditions of Dalits in Hyderabad at the time.\n*   **P.R. Venkat Swamy** described his entry into the Dalit movement as \"a red-letter day in the history of the depressed classes movement.\"\n*   Presided over the **Depressed Classes Conference** held at Parbhani, Marathwada, on **30th May, 1942**.\n*   Convinced the Nizam to contribute **5 lakh rupees** to the people''s education trust created by Dr. B.R. Ambedkar in Aurangabad.\n*   Was part of the Nizam''s delegation to France, along with **Moin Nawaz Jung and Zaheer Ahmed**, for matters relating to the formation of the Nizam State.\n*   Explained the conditions of Dalits at the **United Nations Security Council** and other international forums.\n*   Installed statues of Ambedkar at **Bidar** as a mark of self-respect for Dalits.\n*   In **1954**, became president of the **All India Depressed Classes Association**.\n\n### P.R. Venkat Swamy\n\n*   Wrote a book on Telangana''s Dalit movement titled **\"Our Struggles for Emancipation.\"**", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter23-telangana-adi-hindu-movement-p5", "partName": "Dalit Press and Literature", "bodyMd": "### Dalit Newspapers\n\n| Newspaper | Details |\n|---|---|\n| The Panchama (1918) | First Dalit newspaper published in Telangana; English monthly magazine; edited by **J.S. Mathaiah** |\n| Bhagya Nagar (1931) | Started by Bhagya Reddy Varma; renamed **Adi Hindu Newspaper** in 1937 |\n\n### Important Literary Works of Dalits\n\n*   **Unnava Lakshmi Narayana** — _Maalapalli_\n*   **Boyi Bhimanna** — _Paleru nundi Padmashri varaku_ (Paleru to Padmashri); popularized the term **\"Mamalu\"** (Mala–Madiga)\n*   **Gurram Jashuva** — _Gabbilam_", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter23-telangana-adi-hindu-movement';
